public class Main {
    public static void main(String[] args) {
        String httpRequest = "GET /index.html HTTP/1.1";

        String onTheWire = encapsulate(httpRequest);
        System.out.println("On the wire: " + onTheWire);

        String recovered = decapsulate(onTheWire);
        System.out.println("Recovered at the application layer: " + recovered);
        System.out.println("Matches original: " + recovered.equals(httpRequest));
    }

    // Each layer wraps the payload from the layer above with its own header, in
    // order: presentation (TLS), transport (TCP), network (IP), data link (Ethernet).
    static String encapsulate(String payload) {
        String presentationLayer = "[TLS]" + payload;
        String transportLayer = "[TCP:port=443]" + presentationLayer;
        String networkLayer = "[IP:dst=93.184.216.34]" + transportLayer;
        String dataLinkLayer = "[ETH:dstMac=AA:BB:CC:DD:EE:FF]" + networkLayer;
        return dataLinkLayer;
    }

    // Each layer strips its own header in reverse order, from the wire back up to the application.
    static String decapsulate(String frame) {
        String afterEthernet = stripHeader(frame, "ETH");
        System.out.println("After removing the Ethernet frame: " + afterEthernet);
        String afterIp = stripHeader(afterEthernet, "IP");
        System.out.println("After removing the IP header: " + afterIp);
        String afterTcp = stripHeader(afterIp, "TCP");
        System.out.println("After removing the TCP header: " + afterTcp);
        String afterTls = stripHeader(afterTcp, "TLS");
        System.out.println("After removing the TLS wrapper: " + afterTls);
        return afterTls;
    }

    static String stripHeader(String data, String expectedTag) {
        int end = data.indexOf(']');
        String tag = data.substring(1, end);
        if (!tag.startsWith(expectedTag)) {
            throw new IllegalStateException("Expected " + expectedTag + " header, found " + tag);
        }
        return data.substring(end + 1);
    }
}

